CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 NUMERIC DEFAULT 'd', c1 VARCHAR(10), c2 TEXT CHECK(c2 IS NULL OR length(c2) < 40));
INSERT OR IGNORE INTO t0(c0, c1, c2) VALUES(0, 1e308, 3);
