CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 VARCHAR(10) CHECK(c0 IS NULL OR length(c0) < 40), c1 INTEGER DEFAULT 'd', c2 INTEGER, c3 NUMERIC, ref INTEGER REFERENCES t0(id));
